async function scanBundle(input, deliver) {
  let count = 0;
  let lineNumber = 1;
  const pendingParts = [];

  try {
    const decoder = new TextDecoder("utf-8", { fatal: true });

    const handleLine = async (rawLine) => {
      if (rawLine.endsWith("\r")) {
        rawLine = rawLine.slice(0, -1);
      }

      const currentLine = lineNumber++;

      if (rawLine.trim().length === 0) {
        return false;
      }

      let value;
      try {
        value = JSON.parse(rawLine);
      } catch {
        const error = new Error("Invalid JSON on line " + currentLine);
        error.code = "BAD_LINE";
        error.line = currentLine;
        throw error;
      }

      count += 1;
      const result = await deliver(value, currentLine);
      return result === false;
    };

    const consumeText = async (text) => {
      let start = 0;

      while (true) {
        const end = text.indexOf("\n", start);

        if (end === -1) {
          if (start < text.length) {
            pendingParts.push(text.slice(start));
          }
          return false;
        }

        if (end > start) {
          pendingParts.push(text.slice(start, end));
        }

        const line = pendingParts.join("");
        pendingParts.length = 0;

        if (await handleLine(line)) {
          return true;
        }

        start = end + 1;
      }
    };

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        break;
      }

      if (await consumeText(decoder.decode(chunk, { stream: true }))) {
        return count;
      }
    }

    if (await consumeText(decoder.decode())) {
      return count;
    }

    if (pendingParts.length !== 0) {
      const finalLine = pendingParts.join("");
      pendingParts.length = 0;
      await handleLine(finalLine);
    }

    return count;
  } finally {
    await input.close();
  }
}
